/**
 * Writes a whole import in one transaction: missing labels, the issues in
 * file order (numbered after the project's highest number), their label
 * links and the import record that makes a replay recognisable.
 */
export async function insertImportedIssues(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  authorId: UserId,
  rows: readonly (Omit<ImportIssueRowInput, "assigneeEmail" | "labels"> & {
    assigneeId: UserId | null;
    labels: readonly string[];
  })[],
): Promise<readonly Issue[]> {
  const db = getDb();

  return db.transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map<string, LabelId>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, orgId))
        .all()
        .map((label) => [label.name, label.id as LabelId]),
    );
    for (const row of rows) {
      for (const name of row.labels) {
        if (labelIdByName.has(name)) continue;
        const created = tx
          .insert(labels)
          .values({
            id: newId(),
            orgId,
            name,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .returning({ id: labels.id })
          .get();
        labelIdByName.set(name, created.id as LabelId);
      }
    }

    const top = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)))
      .get();
    let number = top?.value ?? 0;

    const created: Issue[] = [];
    for (const row of rows) {
      number += 1;
      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = [
        ...new Set(row.labels.map((name) => labelIdByName.get(name) as LabelId)),
      ];
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }
      created.push(toIssue(inserted, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        projectId,
        importKey,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return created;
  });
}

/** Active, non-removed members of the org keyed by lower-cased email. */
export async function mapActiveMemberEmails(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();
  return new Map(rows.map((r) => [r.email.toLowerCase(), r.userId as UserId]));
}
